import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

const Booking = () => {
  const { movieId } = useParams();
  const navigate = useNavigate();
  const [movie, setMovie] = useState(null);
  const [selectedSeats, setSelectedSeats] = useState([]);
  const [showTime, setShowTime] = useState('');
  const [language, setLanguage] = useState('EN');
  const [parking, setParking] = useState(false);
  const [food, setFood] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchMovie();
  }, [movieId]);

  const fetchMovie = async () => {
    try {
      const response = await axios.get(`http://localhost:8080/api/movies/${movieId}`);
      setMovie(response.data);
    } catch (error) {
      console.error('Error fetching movie:', error);
    } finally {
      setLoading(false);
    }
  };

  // Generate theater seats layout
  const generateSeats = () => {
    const seats = [];
    const rows = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];
    const seatsPerRow = [8, 12, 12, 12, 12, 12, 8, 8];

    rows.forEach((row, rowIndex) => {
      const rowSeats = [];
      const seatCount = seatsPerRow[rowIndex];

      for (let i = 1; i <= seatCount; i++) {
        const isBooked = Math.random() > 0.7; // Simulate some booked seats
        rowSeats.push({
          id: `${row}${i}`,
          row: row,
          number: i,
          isBooked: isBooked,
          price: rowIndex < 3 ? 15 : 12, // Front rows more expensive
          type: rowIndex < 3 ? 'premium' : 'standard'
        });
      }

      seats.push(rowSeats);
    });

    return seats;
  };

  const [seats] = useState(generateSeats());

  const handleSeatClick = (seat) => {
    if (seat.isBooked) return;

    const isSelected = selectedSeats.find(s => s.id === seat.id);

    if (isSelected) {
      setSelectedSeats(selectedSeats.filter(s => s.id !== seat.id));
    } else {
      setSelectedSeats([...selectedSeats, seat]);
    }
  };

  const calculateTotal = () => {
    const seatTotal = selectedSeats.reduce((sum, seat) => sum + seat.price, 0);
    const foodTotal = food.reduce((sum, item) => sum + item.price, 0);
    const parkingCost = parking ? 5 : 0;
    return seatTotal + foodTotal + parkingCost;
  };

  const handleBooking = () => {
    if (selectedSeats.length === 0) {
      alert(language === 'EN' ? 'Please select at least one seat' : 'कृपया एक सीट चुनें');
      return;
    }

    const bookingData = {
      movieId: movie.movieId,
      seats: selectedSeats,
      showTime,
      food,
      parking,
      total: calculateTotal()
    };

    // Here you would send bookingData to backend
    console.log('Booking data:', bookingData);
    alert(language === 'EN' ? 'Booking confirmed!' : 'बुकिंग की पुष्टि!');
    navigate('/dashboard');
  };

  const foodOptions = [
    { id: 1, name: language === 'EN' ? 'Popcorn' : 'पॉपकॉर्न', price: 5 },
    { id: 2, name: language === 'EN' ? 'Soda' : 'सोडा', price: 3 },
    { id: 3, name: language === 'EN' ? 'Nachos' : 'नाचोस', price: 4 },
    { id: 4, name: language === 'EN' ? 'Candy' : 'कैंडी', price: 2 }
  ];

  if (loading) {
    return (
      <div className="container">
        <div style={{ textAlign: 'center', padding: '8rem' }}>
          <h2>Loading booking details...</h2>
        </div>
      </div>
    );
  }

  if (!movie) {
    return (
      <div className="container">
        <div style={{ textAlign: 'center', padding: '8rem' }}>
          <h2>Movie not found</h2>
        </div>
      </div>
    );
  }

  return (
    <div>
      {/* Hero Section */}
      <div className="hero">
        <div className="hero-content">
          <h1 className="hero-title">
            {language === 'EN' ? 'SELECT YOUR SEATS' : 'अपनी सीटें चुनें'}
          </h1>
          <p className="hero-subtitle">
            {language === 'EN' 
              ? `Book tickets for ${movie.title}` 
              : `${movie.title} के लिए टिकट बुक करें`}
          </p>
        </div>
      </div>

      {/* Language Toggle */}
      <div className="language-toggle">
        <button 
          className={`language-btn ${language === 'EN' ? 'active' : ''}`}
          onClick={() => setLanguage('EN')}
        >
          EN
        </button>
        <button 
          className={`language-btn ${language === 'HI' ? 'active' : ''}`}
          onClick={() => setLanguage('HI')}
        >
          हिं
        </button>
      </div>

      <div className="container">
        <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '32px', marginBottom: '48px' }}>
          {/* Movie Info */}
          <div className="theater-container">
            <div style={{ marginBottom: '24px' }}>
              <img 
                src={movie.posterUrl || 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=300&h=450&fit=crop'} 
                alt={movie.title}
                style={{ 
                  width: '100%', 
                  height: '300px', 
                  objectFit: 'cover', 
                  borderRadius: '12px',
                  marginBottom: '16px'
                }}
              />
              <h2 style={{ color: 'var(--primary-gold)', marginBottom: '8px' }}>{movie.title}</h2>
              <p style={{ color: 'var(--text-secondary)', marginBottom: '16px' }}>{movie.description}</p>
              <div style={{ display: 'flex', gap: '16px' }}>
                <span>⏱️ {movie.durationMinutes}min</span>
                <span>🎭 {movie.genre}</span>
                <span>⭐ {movie.rating || '8.5'}</span>
              </div>
            </div>

            {/* Show Time Selection */}
            <div style={{ marginBottom: '24px' }}>
              <label className="form-label">
                {language === 'EN' ? 'Select Show Time' : 'शो समय चुनें'}
              </label>
              <select 
                value={showTime}
                onChange={(e) => setShowTime(e.target.value)}
                className="form-input"
              >
                <option value="">{language === 'EN' ? 'Select time' : 'समय चुनें'}</option>
                <option value="10:00">10:00 AM</option>
                <option value="13:00">1:00 PM</option>
                <option value="16:00">4:00 PM</option>
                <option value="19:00">7:00 PM</option>
                <option value="22:00">10:00 PM</option>
              </select>
            </div>

            {/* Theater Layout */}
            <div className="theater-container">
              <div className="theater-screen"></div>

              <div className="seats-grid">
                {seats.map((row, rowIndex) => (
                  <div key={rowIndex} className="seats-row">
                    {row.map(seat => (
                      <div key={seat.id} style={{ position: 'relative' }}>
                        <button
                          className={`seat ${
                            seat.isBooked ? 'booked' : 
                            selectedSeats.find(s => s.id === seat.id) ? 'selected' : 'available'
                          }`}
                          onClick={() => handleSeatClick(seat)}
                          disabled={seat.isBooked}
                        >
                          {seat.number}
                        </button>
                        <span className="seat-label">{seat.row}</span>
                      </div>
                    ))}
                  </div>
                ))}
              </div>

              {/* Legend */}
              <div style={{ 
                display: 'flex', 
                justifyContent: 'center', 
                gap: '24px', 
                marginTop: '32px',
                padding: '16px',
                background: 'rgba(0,0,0,0.3)',
                borderRadius: '8px'
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <div className="seat available" style={{ width: '20px', height: '20px' }}></div>
                  <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                    {language === 'EN' ? 'Available' : 'उपलब्ध'}
                  </span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <div className="seat selected" style={{ width: '20px', height: '20px' }}></div>
                  <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                    {language === 'EN' ? 'Selected' : 'चुना गया'}
                  </span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <div className="seat booked" style={{ width: '20px', height: '20px' }}></div>
                  <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                    {language === 'EN' ? 'Booked' : 'बुक गया'}
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Booking Summary */}
          <div className="booking-summary">
            <h3>
              {language === 'EN' ? 'Booking Summary' : 'बुकिंग सारांश'}
            </h3>

            <div className="booking-item">
              <span>{language === 'EN' ? 'Movie' : 'फिल्म'}</span>
              <span>{movie.title}</span>
            </div>

            <div className="booking-item">
              <span>{language === 'EN' ? 'Seats' : 'सीटें'}</span>
              <span>{selectedSeats.length} × ${selectedSeats.reduce((sum, seat) => sum + seat.price, 0) / selectedSeats.length || 0}</span>
            </div>

            <div className="booking-item">
              <span>{language === 'EN' ? 'Show Time' : 'शो समय'}</span>
              <span>{showTime || language === 'EN' ? 'Not selected' : 'नहीं चुना'}</span>
            </div>

            {/* Add-ons */}
            <div style={{ marginTop: '24px' }}>
              <label className="form-label">
                {language === 'EN' ? 'Add-ons' : 'अतिरिक्त सेवाएं'}
              </label>

              <div style={{ marginBottom: '16px' }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}>
                  <input
                    type="checkbox"
                    checked={parking}
                    onChange={(e) => setParking(e.target.checked)}
                    style={{ width: '16px', height: '16px' }}
                  />
                  <span>{language === 'EN' ? 'Parking ($5)' : 'पार्किंग ($5)'}</span>
                </label>
              </div>

              <div>
                <label className="form-label">
                  {language === 'EN' ? 'Food & Drinks' : 'भोजन और पेय'}
                </label>
                {foodOptions.map(item => (
                  <label key={item.id} style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', cursor: 'pointer' }}>
                    <input
                      type="checkbox"
                      checked={food.find(f => f.id === item.id)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setFood([...food, item]);
                        } else {
                          setFood(food.filter(f => f.id !== item.id));
                        }
                      }}
                      style={{ width: '16px', height: '16px' }}
                    />
                    <span>{item.name} (${item.price})</span>
                  </label>
                ))}
              </div>
            </div>

            <div className="booking-total">
              <span>{language === 'EN' ? 'Total' : 'कुल'}</span>
              <span>${calculateTotal()}</span>
            </div>

            <button 
              className="btn btn-primary"
              onClick={handleBooking}
              style={{ width: '100%', marginTop: '24px' }}
              disabled={selectedSeats.length === 0 || !showTime}
            >
              {language === 'EN' ? 'Confirm Booking' : 'बुकिंग पुष्टि करें'}
            </button>

            <button 
              className="btn btn-secondary"
              onClick={() => navigate('/movies')}
              style={{ width: '100%', marginTop: '12px' }}
            >
              {language === 'EN' ? 'Back to Movies' : 'फिल्मों पर वापस'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Booking;
